package com.mahesh.empleave.leave;
import com.mahesh.empleave.audit.*;import com.mahesh.empleave.holiday.*;import com.mahesh.empleave.leavebalance.*;import com.mahesh.empleave.leavetype.*;import com.mahesh.empleave.notification.*;import com.mahesh.empleave.user.*;import lombok.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;import java.util.*;import java.util.stream.*;
@Service @RequiredArgsConstructor public class LeaveService {private final LeaveRepository leaves;private final UserRepository users;private final LeaveTypeRepository types;private final LeaveBalanceRepository balances;private final BalanceTransactionRepository transactions;private final HolidayRepository holidays;private final AuditService audit;private final NotificationService notifications;
 public List<LeaveApplication> historyFor(AppUser user){return leaves.findByApplicantOrderByIdDesc(user);}
 public int workingDays(LocalDate from,LocalDate to){var off=holidays.findByHolidayDateBetween(from,to).stream().map(Holiday::getHolidayDate).collect(Collectors.toSet());return (int)from.datesUntil(to.plusDays(1)).filter(d->d.getDayOfWeek()!=DayOfWeek.SATURDAY&&d.getDayOfWeek()!=DayOfWeek.SUNDAY&&!off.contains(d)).count();}
 public int validateApplication(String email,String type,LocalDate from,LocalDate to){if(from==null||to==null||from.isBefore(LocalDate.now())||to.isBefore(from))throw new IllegalArgumentException("Dates must be valid and not in the past");var user=users.findByEmail(email).orElseThrow();var leaveType=types.findByNameAndActiveTrue(type).orElseThrow(()->new IllegalArgumentException("Unknown or inactive leave type"));if(!leaves.overlaps(user,from,to).isEmpty())throw new IllegalStateException("Overlapping leave request exists");int days=workingDays(from,to);if(days==0)throw new IllegalArgumentException("Leave must include a working day");var balance=balances.findByUser(user).stream().filter(item->item.getLeaveType().getName().equals(leaveType.getName())).findFirst().orElseThrow(()->new IllegalStateException("No leave entitlement configured"));if(balance.getRemainingDays().compareTo(BigDecimal.valueOf(days))<0)throw new IllegalStateException("Insufficient leave balance");return days;}
 @Transactional public LeaveApplication apply(String email,String type,LocalDate from,LocalDate to,String reason){int days=validateApplication(email,type,from,to);var user=users.findByEmail(email).orElseThrow();var leaveType=types.findByNameAndActiveTrue(type).orElseThrow();var result=leaves.save(new LeaveApplication(user,leaveType.getName(),from,to,days,reason));audit.log(user,"LEAVE_APPLIED","LEAVE",result.getId());if(user.getManager()!=null)notifications.notify(user.getManager(),user.getFullName()+" submitted a leave request");return result;}
@Transactional public LeaveApplication approve(String actor,Long id){var reviewer=users.findByEmail(actor).orElseThrow();var l=leaves.findById(id).orElseThrow();if(l.getApplicant().getId().equals(reviewer.getId()))throw new IllegalArgumentException("Self approval is prohibited");if(reviewer.getRole()!=Role.ADMIN&&(l.getApplicant().getManager()==null||!l.getApplicant().getManager().getId().equals(reviewer.getId())))throw new SecurityException("You may only approve your direct reports");var type=types.findByNameAndActiveTrue(l.getLeaveType()).orElseThrow();var balance=balances.findForUpdate(l.getApplicant(),type).orElseThrow(()->new IllegalStateException("No leave entitlement configured"));if(transactions.existsByApplication(l))throw new IllegalStateException("Leave has already been accounted for");balance.debit(l.getWorkingDays());l.approve();transactions.save(new BalanceTransaction(balance,l,BigDecimal.valueOf(-l.getWorkingDays())));audit.log(reviewer,"LEAVE_APPROVED","LEAVE",l.getId());notifications.notify(l.getApplicant(),"Your leave request was approved");return l;}
 @Transactional public LeaveApplication reject(String actor,Long id,String reason){if(reason==null||reason.isBlank())throw new IllegalArgumentException("Rejection reason is required");var reviewer=users.findByEmail(actor).orElseThrow();var l=leaves.findById(id).orElseThrow();if(l.getApplicant().getId().equals(reviewer.getId()))throw new IllegalArgumentException("Self review is prohibited");if(reviewer.getRole()!=Role.ADMIN&&(l.getApplicant().getManager()==null||!l.getApplicant().getManager().getId().equals(reviewer.getId())))throw new SecurityException("You may only review your direct reports");l.reject(reason);audit.log(reviewer,"LEAVE_REJECTED","LEAVE",l.getId());notifications.notify(l.getApplicant(),"Your leave request was rejected: "+reason);return l;}
 @Transactional public LeaveApplication cancel(String email,Long id){var actor=users.findByEmail(email).orElseThrow();var l=leaves.findById(id).orElseThrow();if(!l.getApplicant().getId().equals(actor.getId()))throw new SecurityException("Not your request");boolean restore=l.cancel();if(restore){var type=types.findByNameAndActiveTrue(l.getLeaveType()).orElseThrow();var b=balances.findForUpdate(actor,type).orElseThrow();b.credit(l.getWorkingDays());transactions.save(new BalanceTransaction(b,l,BigDecimal.valueOf(l.getWorkingDays())));}audit.log(actor,"LEAVE_CANCELLED","LEAVE",l.getId());if(actor.getManager()!=null)notifications.notify(actor.getManager(),actor.getFullName()+" cancelled a leave request");return l;}}
